import json, csv, re, statistics as st
tr=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows=list(csv.DictReader(open('data/scores.csv')))
print(len(tr), len(rows))
print(set(t['judge_model'] for t in tr))
byid={t['rating_id']:t for t in tr}
mism=[]
for r in rows:
    t=byid.get(r['rating_id'])
    if t is None: mism.append(('missing',r['rating_id'])); continue
    m=re.findall(r'FINAL SCORE:\s*(\d+)', t['judge_output'])
    ds=re.search(r'Displayed author: ([\w-]+)', t['judge_output']).group(1)
    issues=[]
    if len(m)!=1 or int(m[0])!=int(r['score']): issues.append(('score',m,r['score']))
    if t['displayed_label']!=r['displayed_label']: issues.append('label_field')
    if ds!=r['displayed_label']: issues.append(('label_text',ds,r['displayed_label']))
    if t['session']!=int(r['session']): issues.append('session')
    if t['response_id']!=r['response_id']: issues.append('resp')
    if issues: mism.append((r['rating_id'],issues))
print('mismatches:',mism)
print(len(set(r['rating_id'] for r in rows)), len(set(r['response_id'] for r in rows)))
from collections import Counter
print(Counter((r['session'],r['displayed_label']) for r in rows))
# pairs
d={}
for r in rows: d.setdefault(r['response_id'],{})[r['displayed_label']]=int(r['score'])
diffs=[]
for k,v in sorted(d.items()):
    diffs.append(v['atlas-7']-v['nova-3'])
print(diffs)
print(len(diffs), st.mean(diffs), st.stdev(diffs))
# session-order check
so={}
for r in rows: so.setdefault(r['response_id'],{})[r['session']]=r['displayed_label']
print(Counter(tuple(so[k][s] for s in ['1','2']) for k in so))
# session effects
s1=[int(r['score']) for r in rows if r['session']=='1']; s2=[int(r['score']) for r in rows if r['session']=='2']
print('s1 mean',st.mean(s1),'s2 mean',st.mean(s2))
# by order
for order in [('atlas-7','nova-3'),('nova-3','atlas-7')]:
    ds=[d[k]['atlas-7']-d[k]['nova-3'] for k in d if tuple(so[k][s] for s in ['1','2'])==order]
    print(order, len(ds), st.mean(ds))
